import {escapeHtml as esc} from './facts-core.js';
const NAMES={'shape-choice':'Shape Spotter','shape-typed':'Postal Pro',mapquest:'Map Quest',population:'Population Showdown',area:'Size Showdown',timeline:'Statehood Timeline','neighbors-one':'One of my Neighbors','neighbors-all':'All my Neighbors'};
const accuracy=(correct,total)=>total?Math.round(correct/total*100)+'%':'—';
const when=date=>esc(new Date(date).toLocaleString());
const seconds=ms=>(ms/1000).toFixed(1)+'s';
export function progressResults(progress,locations,practiceIds,challengeIds){
 const quizKey=[...practiceIds].sort().join('-'),stats=progress.sprintStats||[],quiz=stats.find(s=>s.mode==='quiz'&&s.pool.join('-')===quizKey),challenge=stats.find(s=>s.mode==='challenge');
 function sprintCard(s,mode,pool){const challenge=mode==='challenge',title=challenge?'120-second Challenge':'60-second Quiz';
 return `<section class="game-progress-card"><h3>State Sprint — ${title}</h3><p>${challenge?'All 50 U.S. states':`${pool.length} practice locations`}</p>${s?`<p><strong>Best: ${s.bestCorrect} correct</strong> · ${s.runs} completed ${s.runs===1?'run':'runs'}</p>${s.runs?`<p>Best points: ${s.bestPoints.toLocaleString()} · longest streak: ${s.bestStreak}</p>`:'<p>Earlier best retained; detailed history starts with this update.</p>'}${challenge?`<p>Fastest all 50 answered: <strong>${s.fastestMs===null?'—':seconds(s.fastestMs)}</strong><br>Fastest perfect 50/50: <strong>${s.perfectMs===null?'—':seconds(s.perfectMs)}</strong></p>`:''}${s.history.length?`<details><summary>Recent runs (${s.history.length})</summary><ol class="game-history">${s.history.map(r=>`<li><time>${when(r.date)}</time><strong>${r.correct} / ${r.attempted} correct · ${accuracy(r.correct,r.attempted)}</strong><span>${r.points.toLocaleString()} points · streak ${r.longest} · ${seconds(r.elapsedMs)}</span><span>${r.completed?(r.correct===pool.length?'Perfect '+pool.length+'/'+pool.length:'Completed all '+pool.length):'Time expired'}</span></li>`).join('')}</ol></details>`:''}`:'<p>No completed runs yet.</p>'}<details><summary>Locations in this record</summary><p>${pool.map(a=>esc(locations.find(s=>s.abbr===a)?.name||a)).join(', ')}</p></details></section>`;
 }
 const previous=stats.filter(s=>s!==quiz&&s!==challenge);
 return `<h2 class="progress-section-title">State Sprint results</h2>${sprintCard(quiz,'quiz',practiceIds)}${sprintCard(challenge,'challenge',challengeIds)}${previous.length?`<details class="other-pools"><summary>Other Sprint location pools (${previous.length})</summary>${previous.map(s=>sprintCard(s,s.mode,s.pool)).join('')}</details>`:''}<h2 class="progress-section-title">Game results</h2><p class="history-note">Per-game tracking starts with this update. Earlier overall bests are retained above. Recent answers show the last 10 per game; Sprint retains the last 20 runs per pool.</p>${Object.entries(NAMES).map(([key,name])=>{const g=progress.gameStats?.[key];return `<section class="game-progress-card"><h3>${name}</h3>${g?`<p><strong>${g.correct} / ${g.answered} correct · ${accuracy(g.correct,g.answered)}</strong></p><p>Current streak: ${g.streak} · longest: ${g.bestStreak}<br>Total points earned: ${g.points.toLocaleString()}</p>${g.history.length?`<details><summary>Recent answers</summary><ol class="game-history">${g.history.map(r=>`<li><time>${when(r.date)}</time><strong>${r.correct?'Correct':'Incorrect'} · +${r.points} points</strong><span>${esc(r.label||'')}</span></li>`).join('')}</ol></details>`:''}`:'<p>No answers recorded yet.</p>'}</section>`;}).join('')}`;
}
